import { readFile } from "node:fs/promises";
import { stripTypeScriptTypes } from "node:module";
import { join, relative } from "node:path";
const raw = await readFile("packages/scheduler/src/package-boundary.test.ts", "utf8");
const cutoff = raw.indexOf('it("keeps scheduler registrars behind');
if (cutoff < 0) throw new Error("PROBE_ANCHOR_ABSENT");
let subject = raw.slice(0, cutoff)
  .replace('import { expect, it } from "vitest";', "")
  .replace(/const repositoryRoot = fileURLToPath\([^;]+;/u,
    `const repositoryRoot = ${JSON.stringify(process.cwd())};`);
subject += "\nexport { sourceFiles, containsForbiddenSchedulerImport };";
const m = await import("data:text/javascript;base64," +
  Buffer.from(stripTypeScriptTypes(subject)).toString("base64"));
const files = (await Promise.all(["adapters","apps","packages"]
  .map(root => m.sourceFiles(join(process.cwd(),root))))).flat();
let completed = 0;
let firstFailure;
const violations = [];
for (const file of files) {
  try {
    if (m.containsForbiddenSchedulerImport(await readFile(file,"utf8")))
      violations.push(relative(process.cwd(),file));
    completed++;
  } catch (error) {
    firstFailure = {path:relative(process.cwd(),file),error:String(error)};
    break;
  }
}
console.log(JSON.stringify({enumerated:files.length,completed,
  attempted:completed+Number(Boolean(firstFailure)),
  unattempted:files.length-completed-Number(Boolean(firstFailure)),
  firstFailure,violationsBeforeFailure:violations,
  finalEnumeratedPath:relative(process.cwd(),files.at(-1))}));

